function describeReading(reading) {
  if (!reading || typeof reading !== 'object' || Array.isArray(reading)) {
    throw new TypeError('reading must be an object');
  }
  const numbers = ['temperature', 'feelsLike', 'windSpeed', 'windDegrees', 'pressure', 'humidity'];
  if (!Number.isInteger(reading.hour) || reading.hour < 0 || reading.hour > 23 ||
      typeof reading.condition !== 'string' ||
      numbers.some(key => !Number.isFinite(reading[key])) ||
      reading.windSpeed < 0 || reading.humidity < 0 || reading.humidity > 100) {
    throw new TypeError('invalid reading');
  }
  const daytime = reading.hour >= 6 && reading.hour <= 18;
  const condition = reading.condition.trim().toLowerCase();
  let icon = 'unknown';
  if (condition === 'clear') icon = daytime ? 'clear-day' : 'clear-night';
  if (condition === 'cloudy' || condition === 'overcast') icon = daytime ? 'cloud-day' : 'cloud-night';
  const displayHour = reading.hour % 12 || 12;
  return {
    time: String(displayHour).padStart(2, '0') + ':00 ' + (reading.hour < 12 ? 'AM' : 'PM'),
    icon,
    temperature: reading.temperature,
    feelsLike: reading.feelsLike,
    pressure: reading.pressure,
    humidity: reading.humidity,
    windRotation: ((reading.windDegrees % 360) + 360) % 360,
    windScale: 1 + Math.min(reading.windSpeed, 40) / 40,
    moistureScale: 0.5 + reading.humidity / 200
  };
}

module.exports = { describeReading };

