'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['describeReading']);
const { describeReading } = api;

const input = { hour: 6, condition: '  CLEAR  ', temperature: 21.5, feelsLike: 20, windSpeed: 20, windDegrees: -30, pressure: 1005, humidity: 50 };
const snapshot = { ...input };
const result = describeReading(input);
assert.deepEqual(result, {
  time: '06:00 AM', icon: 'clear-day', temperature: 21.5, feelsLike: 20,
  pressure: 1005, humidity: 50, windRotation: 330, windScale: 1.5, moistureScale: 0.75
});
assert.deepEqual(input, snapshot);
assert.notStrictEqual(result, input);

const cases = [
  [{ hour: 0, condition: 'clear', temperature: 0, feelsLike: -2, windSpeed: 0, windDegrees: 720, pressure: 0, humidity: 0 }, { time: '12:00 AM', icon: 'clear-night', windRotation: 0, windScale: 1, moistureScale: 0.5 }],
  [{ hour: 17, condition: 'Cloudy', temperature: 1, feelsLike: 2, windSpeed: 40, windDegrees: 361.5, pressure: 3, humidity: 100 }, { time: '05:00 PM', icon: 'cloud-day', windRotation: 1.5, windScale: 2, moistureScale: 1 }],
  [{ hour: 18, condition: ' overcast ', temperature: 1, feelsLike: 2, windSpeed: 80, windDegrees: -720, pressure: 3, humidity: 25 }, { time: '06:00 PM', icon: 'cloud-night', windRotation: 0, windScale: 2, moistureScale: 0.625 }],
  [{ hour: 12, condition: 'rain', temperature: 1, feelsLike: 2, windSpeed: 1, windDegrees: 90, pressure: 3, humidity: 10 }, { time: '12:00 PM', icon: 'unknown', windRotation: 90, windScale: 1.025, moistureScale: 0.55 }]
];
for (const [reading, expected] of cases) {
  const actual = describeReading(reading);
  assert.equal(actual.time, expected.time);
  assert.equal(actual.icon, expected.icon);
  assert.equal(actual.windRotation, expected.windRotation);
  assert.equal(actual.windScale, expected.windScale);
  assert.equal(actual.moistureScale, expected.moistureScale);
  assert.equal(actual.temperature, reading.temperature);
  assert.equal(actual.feelsLike, reading.feelsLike);
  assert.equal(actual.pressure, reading.pressure);
  assert.equal(actual.humidity, reading.humidity);
}

const valid = { hour: 10, condition: 'clear', temperature: 1, feelsLike: 1, windSpeed: 1, windDegrees: 1, pressure: 1, humidity: 1 };
for (const patch of [{ hour: -1 }, { hour: 24 }, { hour: 1.5 }, { condition: null }, { temperature: NaN }, { feelsLike: Infinity }, { windSpeed: -1 }, { windDegrees: NaN }, { pressure: Infinity }, { humidity: -1 }, { humidity: 101 }]) {
  assert.throws(() => describeReading({ ...valid, ...patch }), TypeError);
}
for (const bad of [null, [], 'reading']) assert.throws(() => describeReading(bad), TypeError);

